import subprocess, struct, zlib
def run(args):
    import subprocess
    p=subprocess.run(["./executable"]+args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.stdout, p.stderr, p.returncode

def make_png(width, height, pixels):
    def png_chunk(t,d):
        import struct, zlib
        c=struct.pack(">I", len(d)) + t + d
        crc=zlib.crc32(t+d) & 0xffffffff
        return c+struct.pack(">I",crc)
    sig=b'\x89PNG\r\n\x1a\n'
    ihdr=struct.pack(">IIBBBBB", width,height,8,6,0,0,0)
    raw=b''.join(b'\x00'+b''.join(struct.pack("BBBB", *(p if len(p)==4 else (*p,255))) for p in row) for row in pixels)
    comp=zlib.compress(raw)
    return sig+png_chunk(b'IHDR',ihdr)+png_chunk(b'IDAT',comp)+png_chunk(b'IEND',b'')

def bchr(n): return bytes([n])

for tc,tr in [(4,4),(4,2),(8,4)]:
    out,_,_=run(["-tc",str(tc),"-tr",str(tr),"/tmp/test10x10.png"])
    print(f"tc{tc} tr{tr} lines {out.count(bchr(10))} first line len {len(out.split(bchr(10))[0]) if out else 0}")

for s in [0,1,2]:
    for tc,tr in [(8,4),(4,8),(10,10),(80,24)]:
        out,_,_=run(["-s",str(s),"-tc",str(tc),"-tr",str(tr),"/tmp/test8x4.png"])
        print(f"s{s} tc{tc} tr{tr} lines {out.count(bchr(10))} len {len(out)}")

pixels = [[(255,0,0,255)]]
png = make_png(1,1,pixels)
open("/tmp/test1x1.png","wb").write(png)
for s in [0,1,2]:
    out,_,_=run(["-s",str(s),"-tc","4","-tr","4","/tmp/test1x1.png"])
    print(f"1x1 s{s} -> len {len(out)} lines {out.count(bchr(10))} {repr(out[:200])}")

# Test 4x2 fit more
pixels = [[(255,0,0,255),(0,255,0,255),(0,0,255,255),(255,255,255,255)] for _ in range(2)]
png = make_png(4,2,pixels)
open("/tmp/test4x2.png","wb").write(png)
for s in [0,1,2]:
    for tc,tr in [(4,2),(8,4),(4,4)]:
        out,_,_=run(["-s",str(s),"-tc",str(tc),"-tr",str(tr),"/tmp/test4x2.png"])
        print(f"4x2 s{s} tc{tc} tr{tr} lines {out.count(bchr(10))} len {len(out)} repr {repr(out[:150])}")

