package main

import (
    "fmt"
    "image"
    "image/color"
    "golang.org/x/image/draw"
    "github.com/nfnt/resize"
    "github.com/disintegration/imaging"
)

func makeHalfRB() image.Image {
    img := image.NewRGBA(image.Rect(0,0,2,4))
    for y:=0;y<4;y++{
        for x:=0;x<2;x++{
            var c color.RGBA
            if y<2 {
                c = color.RGBA{255,0,0,255}
            } else {
                c = color.RGBA{0,0,255,255}
            }
            img.Set(x,y,c)
        }
    }
    return img
}

func show(img image.Image) {
    b:=img.Bounds()
    for y:=b.Min.Y; y<b.Max.Y; y++{
        for x:=b.Min.X; x<b.Max.X; x++{
            r,g,b,_:=img.At(x,y).RGBA()
            fmt.Printf("%d,%d,%d ", r>>8,g>>8,b>>8)
        }
        fmt.Println()
    }
}

func testResize() {
    src:=makeHalfRB()
    fmt.Println("src")
    show(src)
    // target 2x4 (same)
    for _, method := range []struct{name string; fn func() image.Image}{
        {"nearest draw", func() image.Image{
            dst:=image.NewRGBA(image.Rect(0,0,2,4))
            draw.NearestNeighbor.Scale(dst, dst.Bounds(), src, src.Bounds(), draw.Over, nil)
            return dst
        }},
        {"approx bilinear", func() image.Image{
            dst:=image.NewRGBA(image.Rect(0,0,2,4))
            draw.ApproxBiLinear.Scale(dst, dst.Bounds(), src, src.Bounds(), draw.Over, nil)
            return dst
        }},
        {"bilinear", func() image.Image{
            dst:=image.NewRGBA(image.Rect(0,0,2,4))
            draw.BiLinear.Scale(dst, dst.Bounds(), src, src.Bounds(), draw.Over, nil)
            return dst
        }},
        {"catmullrom", func() image.Image{
            dst:=image.NewRGBA(image.Rect(0,0,2,4))
            draw.CatmullRom.Scale(dst, dst.Bounds(), src, src.Bounds(), draw.Over, nil)
            return dst
        }},
        {"nfnt nearest", func() image.Image{
            return resize.Resize(2,4, src, resize.NearestNeighbor)
        }},
        {"nfnt bilinear", func() image.Image{
            return resize.Resize(2,4, src, resize.Bilinear)
        }},
        {"nfnt bicubic", func() image.Image{
            return resize.Resize(2,4, src, resize.Bicubic)
        }},
        {"nfnt mitchell", func() image.Image{
            return resize.Resize(2,4, src, resize.MitchellNetravali)
        }},
        {"nfnt lanczos2", func() image.Image{
            return resize.Resize(2,4, src, resize.Lanczos2)
        }},
        {"nfnt lanczos3", func() image.Image{
            return resize.Resize(2,4, src, resize.Lanczos3)
        }},
        {"imaging nearest", func() image.Image{
            return imaging.Resize(src, 2,4, imaging.NearestNeighbor)
        }},
        {"imaging linear", func() image.Image{
            return imaging.Resize(src, 2,4, imaging.Linear)
        }},
        {"imaging box", func() image.Image{
            return imaging.Resize(src, 2,4, imaging.Box)
        }},
        {"imaging lanczos", func() image.Image{
            return imaging.Resize(src, 2,4, imaging.Lanczos)
        }},
        {"imaging catmullrom", func() image.Image{
            return imaging.Resize(src, 2,4, imaging.CatmullRom)
        }},
        {"imaging mitchell", func() image.Image{
            return imaging.Resize(src, 2,4, imaging.MitchellNetravali)
        }},
    } {
        dst:=method.fn()
        fmt.Printf("method %s\n", method.name)
        show(dst)
    }
}

func main() { testResize() }
