func isHexDigit(c byte) bool {
    return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

func parseMatte(s string) (color.RGBA, error) {
    // Empty means default 000000
    if s == "" {
        return color.RGBA{0, 0, 0, 255}, nil
    }
    // Check length rules
    l := len(s)
    if l == 1 || l == 2 || l == 4 {
        return color.RGBA{}, fmt.Errorf("color: %s is not a hex-color", s)
    }
    // For len 3: must be all hex
    if l == 3 {
        for i := 0; i < 3; i++ {
            if !isHexDigit(s[i]) {
                return color.RGBA{}, fmt.Errorf("color: %s is not a hex-color", s)
            }
        }
        // Parse as 3-digit hex doubled
        r, _ := strconv.ParseUint(s[0:1], 16, 8)
        g, _ := strconv.ParseUint(s[1:2], 16, 8)
        b, _ := strconv.ParseUint(s[2:3], 16, 8)
        // Doubling: 0xf -> 0xff = f*16+f = f*17
        rr := uint8(r*17)
        gg := uint8(g*17)
        bb := uint8(b*17)
        return color.RGBA{rr, gg, bb, 255}, nil
    }
    if l == 5 {
        for i := 0; i < 5; i++ {
            if !isHexDigit(s[i]) {
                return color.RGBA{}, fmt.Errorf("color: %s is not a hex-color", s)
            }
        }
        r, _ := strconv.ParseUint(s[0:2], 16, 8)
        g, _ := strconv.ParseUint(s[2:4], 16, 8)
        b, _ := strconv.ParseUint(s[4:5], 16, 8)
        // single digit -> *17? Wait earlier we saw 12345 -> 18,52,5 not 85. Let's see: for len5, B is single digit interpreted as 0x0? + digit? Actually "12345" gave B=5 (0x05). That's parse as single digit hex value (0-15) not doubled. For "abcde", B = 0xe =14, not 0xee=238. So for len5, B is single hex digit value (0-15) not doubled.
        // But for len3, B is doubled. For len5, maybe B is single digit *1? Let's test with our earlier data: "abcde" gave (171,205,14) where 14 is 0xe =14 correct.
        // For "fffff" would be ff, ff, 0xf =15, correct.
        return color.RGBA{uint8(r), uint8(g), uint8(b), 255}, nil
    }
    if l >= 6 {
        // For len >=6, we need to decide to parse as 6 or 5.
        // If all first 6 are hex, parse as 6.
        // Else if first 5 are hex, parse as 5 (ignore rest).
        // Else error.
        all6 := true
        for i := 0; i < 6 && i < l; i++ {
            if !isHexDigit(s[i]) {
                all6 = false
                break
            }
        }
        if all6 {
            r, _ := strconv.ParseUint(s[0:2], 16, 8)
            g, _ := strconv.ParseUint(s[2:4], 16, 8)
            b, _ := strconv.ParseUint(s[4:6], 16, 8)
            return color.RGBA{uint8(r), uint8(g), uint8(b), 255}, nil
        }
        // Try first 5
        all5 := true
        for i := 0; i < 5 && i < l; i++ {
            if !isHexDigit(s[i]) {
                all5 = false
                break
            }
        }
        if all5 {
            r, _ := strconv.ParseUint(s[0:2], 16, 8)
            g, _ := strconv.ParseUint(s[2:4], 16, 8)
            b, _ := strconv.ParseUint(s[4:5], 16, 8)
            return color.RGBA{uint8(r), uint8(g), uint8(b), 255}, nil
        }
        return color.RGBA{}, fmt.Errorf("color: %s is not a hex-color", s)
    }
    // Should not reach
    return color.RGBA{}, fmt.Errorf("color: %s is not a hex-color", s)
}

func blendOver(src color.RGBA, matte color.RGBA) color.RGBA {
    // Alpha blending: matte is opaque, src has alpha.
    // Result = src * alpha/255 + matte * (1-alpha/255)
    // src is already non-premultiplied? In Go, color.RGBA is not premultiplied.
    a := uint16(src.A)
    invA := 255 - a
    r := (uint16(src.R)*a + uint16(matte.R)*invA) / 255
    g := (uint16(src.G)*a + uint16(matte.G)*invA) / 255
    b := (uint16(src.B)*a + uint16(matte.B)*invA) / 255
    return color.RGBA{uint8(r), uint8(g), uint8(b), 255}
}

func main() {
    log.SetPrefix("[PIXTERM ERROR] ")
    // Custom flag set to handle errors manually
    flagSet := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
    flagSet.SetOutput(os.Stderr) // but we will override usage
    var (
        dMode   int
        sMethod int
        matteStr string
        goFlag  bool
        nobg    bool
        tc      int
        tr      int
        versionFlag bool
        creditsFlag bool
        helpFlag bool
    )
