    flagSet.IntVar(&sMethod, "s", 0, "")
    flagSet.StringVar(&matteStr, "m", "000000", "")
    flagSet.BoolVar(&goFlag, "go", false, "")
    flagSet.BoolVar(&nobg, "nobg", false, "")
    flagSet.IntVar(&tc, "tc", 0, "")
    flagSet.IntVar(&tr, "tr", 0, "")
    flagSet.BoolVar(&versionFlag, "version", false, "")
    flagSet.BoolVar(&creditsFlag, "credits", false, "")
    flagSet.BoolVar(&helpFlag, "help", false, "")
    // Also need -h alias for help
    flagSet.BoolVar(&helpFlag, "h", false, "")

    // Custom usage
    flagSet.Usage = func() {
        printUsage()
    }

    err := flagSet.Parse(os.Args[1:])
    if err != nil {
        // flag parse error -> show usage to stdout and exit 2
        printUsage()
        os.Exit(2)
    }

    // Check version, credits, help precedence
    if versionFlag {
        fmt.Fprintln(os.Stdout, version)
        os.Exit(0)
    }
    if creditsFlag {
        printCredits()
        os.Exit(0)
    }
    if helpFlag {
        printUsage()
        os.Exit(0)
    }

    // Validate flags
    if dMode < 0 || dMode > 2 {
        printUsage()
        os.Exit(2)
    }
    if sMethod < 0 || sMethod > 2 {
        printUsage()
        os.Exit(2)
    }
    // tc and tr: 0 means auto, otherwise must be >=2
    if flagSet.NFlag() > 0 {
        // Check if tc/tr were explicitly set
        tcSet := false
        trSet := false
        flagSet.Visit(func(f *flag.Flag) {
            if f.Name == "tc" {
                tcSet = true
            }
            if f.Name == "tr" {
                trSet = true
            }
