    }

    // Check args
    args := flagSet.Args()
    if len(args) == 0 {
        printUsage()
        os.Exit(2)
    }
    if len(args) > 1 {
        // Original handles extra args as file not found for first arg? Actually we saw "arg1 arg2" gave error open arg1: no such file.
        // But also if version etc. takes precedence, already handled.
