    log.SetPrefix("[PIXTERM ERROR] ")
    log.SetFlags(log.Ldate | log.Ltime)
    fs:=flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    var dMode int
    var sMethod int
    var matteStr string
    var goFlag bool
    var nobg bool
    var tc int
    var tr int
    var versionFlag bool
    var creditsFlag bool
    var helpFlag bool
    fs.IntVar(&dMode, "d", 0, "")
    fs.IntVar(&sMethod, "s", 0, "")
    fs.StringVar(&matteStr, "m", "000000", "")
    fs.BoolVar(&goFlag, "go", false, "")
    fs.BoolVar(&nobg, "nobg", false, "")
    fs.IntVar(&tc, "tc", 0, "")
    fs.IntVar(&tr, "tr", 0, "")
    fs.BoolVar(&versionFlag, "version", false, "")
    fs.BoolVar(&creditsFlag, "credits", false, "")
    fs.BoolVar(&helpFlag, "help", false, "")
    fs.BoolVar(&helpFlag, "h", false, "")

    fs.Usage = func(){ printUsage() }

    err:=fs.Parse(os.Args[1:])
    if err != nil {
        printUsage()
        os.Exit(2)
    }
    if versionFlag { fmt.Fprintln(os.Stdout, version); os.Exit(0) }
    if creditsFlag { printCredits(); os.Exit(0) }
    if helpFlag { printUsage(); os.Exit(0) }

    if dMode<0 || dMode>2 { printUsage(); os.Exit(2) }
    if sMethod<0 || sMethod>2 { printUsage(); os.Exit(2) }

    // Validate tc/tr if explicitly set
    tcSet:=false; trSet:=false
    fs.Visit(func(f *flag.Flag){
        if f.Name=="tc" { tcSet=true }
        if f.Name=="tr" { trSet=true }
    })
    if tcSet && tc!=0 && tc<2 { printUsage(); os.Exit(2) }
    if trSet && tr!=0 && tr<2 { printUsage(); os.Exit(2) }

    matte, err:=parseMatte(matteStr)
    if err != nil {
        printLogo()
        log.Fatalf("matte color : %s is not a hex-color", matteStr)
    }

    args:=fs.Args()
    if len(args)==0 { printUsage(); os.Exit(2) }
    imgPath:=args[0]
    // support extra args? Original handles extra as file not found for first arg if more than 1? But we will ignore extra beyond first.
    // Actually if more than 1 arg, we should treat as error? Original for "arg1 arg2" gave open arg1 error, so use first.
    // Nothing to do.

    var img image.Image
    if strings.HasPrefix(imgPath, "http://") || strings.HasPrefix(imgPath, "https://") {
        resp, err:=http.Get(imgPath)
        if err != nil {
            printLogo()
            log.Fatalf("%v", err)
        }
        defer resp.Body.Close()
        if resp.StatusCode != http.StatusOK {
            printLogo()
            log.Fatalf("ANSImage: image download failed")
        }
        img, _, err = image.Decode(resp.Body)
        if err != nil {
            printLogo()
            log.Fatalf("image: unknown format")
        }
    } else {
        f, err:=os.Open(imgPath)
        if err != nil {
            printLogo()
            // Preserve exact error string: original shows "open <path>: no such file or directory"
            // os.Open error already is that, but we need to format as "open %s: no such file or directory"
            // Use err.Error() directly? It already contains "open <path>: ..."
