func isHexDigit(c byte) bool { return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') }
func parseMatte(s string) (color.RGBA, error) {
    if s == "" { return color.RGBA{0,0,0,255}, nil }
    l:=len(s)
    if l==1||l==2||l==4 { return color.RGBA{}, fmt.Errorf("color: %s is not a hex-color", s) }
    if l==3 {
        for i:=0;i<3;i++ { if !isHexDigit(s[i]) { return color.RGBA{}, fmt.Errorf("color: %s is not a hex-color", s)}}
        r,_:=strconv.ParseUint(s[0:1],16,8); g,_:=strconv.ParseUint(s[1:2],16,8); b,_:=strconv.ParseUint(s[2:3],16,8)
        return color.RGBA{uint8(r*17), uint8(g*17), uint8(b*17), 255}, nil
    }
    if l==5 {
        for i:=0;i<5;i++ { if !isHexDigit(s[i]) { return color.RGBA{}, fmt.Errorf("color: %s is not a hex-color", s)}}
        r,_:=strconv.ParseUint(s[0:2],16,8); g,_:=strconv.ParseUint(s[2:4],16,8); b,_:=strconv.ParseUint(s[4:5],16,8)
        return color.RGBA{uint8(r), uint8(g), uint8(b),255}, nil
    }
    if l>=6 {
        all6:=true; for i:=0;i<6 && i<l;i++ { if !isHexDigit(s[i]) { all6=false; break}}
        if all6 {
            r,_:=strconv.ParseUint(s[0:2],16,8); g,_:=strconv.ParseUint(s[2:4],16,8); b,_:=strconv.ParseUint(s[4:6],16,8)
            return color.RGBA{uint8(r),uint8(g),uint8(b),255}, nil
        }
        all5:=true; for i:=0;i<5 && i<l;i++ { if !isHexDigit(s[i]) { all5=false; break}}
        if all5 {
            r,_:=strconv.ParseUint(s[0:2],16,8); g,_:=strconv.ParseUint(s[2:4],16,8); b,_:=strconv.ParseUint(s[4:5],16,8)
            return color.RGBA{uint8(r),uint8(g),uint8(b),255}, nil
        }
        return color.RGBA{}, fmt.Errorf("color: %s is not a hex-color", s)
    }
    return color.RGBA{}, fmt.Errorf("color: %s is not a hex-color", s)
}
func blendOver(src color.RGBA, matte color.RGBA) color.RGBA {
    a:=uint16(src.A); invA:=255-a
    r:=(uint16(src.R)*a + uint16(matte.R)*invA)/255
    g:=(uint16(src.G)*a + uint16(matte.G)*invA)/255
    b:=(uint16(src.B)*a + uint16(matte.B)*invA)/255
    return color.RGBA{uint8(r),uint8(g),uint8(b),255}
}
type winsize struct { Row, Col, Xpixel, Ypixel uint16 }
func isTerminal(fd int) bool {
    var ws winsize
    _, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
    return err==0 && ws.Col!=0 && ws.Row!=0
}
func getTermSize() (int,int) {
    var ws winsize
    _, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(int(os.Stdout.Fd())), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
    if err!=0 { return 0,0 }
    return int(ws.Col), int(ws.Row)
}
func resizeImage(img image.Image, dstW, dstH int) *image.RGBA {
    srcBounds:=img.Bounds(); srcW:=srcBounds.Dx(); srcH:=srcBounds.Dy()
    if dstW==srcW && dstH==srcH {
        rgba:=image.NewRGBA(image.Rect(0,0,dstW,dstH))
        for y:=0;y<dstH;y++{ for x:=0;x<dstW;x++{ rgba.Set(x,y, img.At(srcBounds.Min.X+x, srcBounds.Min.Y+y)) } }
        return rgba
    }
    dst:=image.NewRGBA(image.Rect(0,0,dstW,dstH))
    for y:=0;y<dstH;y++{
        for x:=0;x<dstW;x++{
            srcX:= (float64(x)+0.5)*float64(srcW)/float64(dstW)-0.5
            srcY:= (float64(y)+0.5)*float64(srcH)/float64(dstH)-0.5
            if srcX<0 { srcX=0 }; if srcY<0 { srcY=0 }
            if srcX>float64(srcW-1) { srcX=float64(srcW-1)}; if srcY>float64(srcH-1) { srcY=float64(srcH-1)}
            x0:=int(srcX); y0:=int(srcY); x1:=x0+1; if x1>=srcW { x1=srcW-1 }; y1:=y0+1; if y1>=srcH { y1=srcH-1 }
            fx:=srcX-float64(x0); fy:=srcY-float64(y0)
            c00:=color.RGBAModel.Convert(img.At(srcBounds.Min.X+x0, srcBounds.Min.Y+y0)).(color.RGBA)
            c10:=color.RGBAModel.Convert(img.At(srcBounds.Min.X+x1, srcBounds.Min.Y+y0)).(color.RGBA)
            c01:=color.RGBAModel.Convert(img.At(srcBounds.Min.X+x0, srcBounds.Min.Y+y1)).(color.RGBA)
            c11:=color.RGBAModel.Convert(img.At(srcBounds.Min.X+x1, srcBounds.Min.Y+y1)).(color.RGBA)
            r:= (1-fx)*(1-fy)*float64(c00.R) + fx*(1-fy)*float64(c10.R) + (1-fx)*fy*float64(c01.R) + fx*fy*float64(c11.R)
            g:= (1-fx)*(1-fy)*float64(c00.G) + fx*(1-fy)*float64(c10.G) + (1-fx)*fy*float64(c01.G) + fx*fy*float64(c11.G)
            b:= (1-fx)*(1-fy)*float64(c00.B) + fx*(1-fy)*float64(c10.B) + (1-fx)*fy*float64(c01.B) + fx*fy*float64(c11.B)
            a:= (1-fx)*(1-fy)*float64(c00.A) + fx*(1-fy)*float64(c10.A) + (1-fx)*fy*float64(c01.A) + fx*fy*float64(c11.A)
            dst.Set(x,y, color.RGBA{uint8(r+0.5), uint8(g+0.5), uint8(b+0.5), uint8(a+0.5)})
        }
    }
    return dst
}
func luminance(r,g,b uint8) float64 { return 0.299*float64(r)+0.587*float64(g)+0.114*float64(b) }

func main() {
    log.SetPrefix("[PIXTERM ERROR] ")
    log.SetFlags(log.Ldate | log.Ltime)
    fs:=flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    var dMode int; var sMethod int; var matteStr string; var goFlag bool; var nobg bool; var tc int; var tr int
    var versionFlag bool; var creditsFlag bool; var helpFlag bool
    fs.IntVar(&dMode, "d", 0, ""); fs.IntVar(&sMethod, "s", 0, "")
    fs.StringVar(&matteStr, "m", "000000", ""); fs.BoolVar(&goFlag, "go", false, "")
    fs.BoolVar(&nobg, "nobg", false, ""); fs.IntVar(&tc, "tc", 0, "")
    fs.IntVar(&tr, "tr", 0, ""); fs.BoolVar(&versionFlag, "version", false, "")
    fs.BoolVar(&creditsFlag, "credits", false, ""); fs.BoolVar(&helpFlag, "help", false, "")
    fs.BoolVar(&helpFlag, "h", false, "")
    fs.Usage = func(){ printUsage() }
    err:=fs.Parse(os.Args[1:])
    if err != nil { printUsage(); os.Exit(2) }
    if versionFlag { fmt.Fprintln(os.Stdout, version); os.Exit(0) }
    if creditsFlag { printCredits(); os.Exit(0) }
    if helpFlag { printUsage(); os.Exit(0) }
    if dMode<0||dMode>2 { printUsage(); os.Exit(2) }
    if sMethod<0||sMethod>2 { printUsage(); os.Exit(2) }
    tcSet:=false; trSet:=false
    fs.Visit(func(f *flag.Flag){ if f.Name=="tc"{ tcSet=true}; if f.Name=="tr"{ trSet=true} })
    if tcSet && tc!=0 && tc<2 { printUsage(); os.Exit(2) }
    if trSet && tr!=0 && tr<2 { printUsage(); os.Exit(2) }
    matte, err:=parseMatte(matteStr)
    if err != nil { printLogo(); log.Fatalf("matte color : %s is not a hex-color", matteStr) }
    args:=fs.Args()
    if len(args)==0 { printUsage(); os.Exit(2) }
    imgPath:=args[0]
    var img image.Image
    if strings.HasPrefix(imgPath, "http://") || strings.HasPrefix(imgPath, "https://") {
        resp, err:=http.Get(imgPath)
        if err != nil { printLogo(); log.Fatalf("%v", err) }
        defer resp.Body.Close()
        if resp.StatusCode!=http.StatusOK { printLogo(); log.Fatalf("ANSImage: image download failed") }
        img, _, err = image.Decode(resp.Body)
        if err != nil { printLogo(); log.Fatalf("image: unknown format") }
    } else {
        f, err:=os.Open(imgPath)
        if err != nil { printLogo(); log.Fatalf("%v", err) }
        defer f.Close()
        img, _, err = image.Decode(f)
        if err != nil { printLogo(); log.Fatalf("image: unknown format") }
    }
    cols:=tc; rows:=tr
    if cols==0||rows==0 {
        isTerm:=isTerminal(int(os.Stdout.Fd()))
        var w,h int
        if isTerm {
            tw,th:=getTermSize()
            w=tw; h=th
        }
        if cols==0 {
            if w!=0 { cols=w } else { cols=80 }
        }
        if rows==0 {
            if h!=0 { rows=h } else {
                if isTerm { rows=24 } else { rows=22 }
            }
        }
    }
    if cols==0 { cols=80 }
    if rows==0 { rows=24 }
    targetW:=cols; targetH:=rows*2
    bounds:=img.Bounds(); srcW:=bounds.Dx(); srcH:=bounds.Dy()
    var scaledW, scaledH int
    var scaledImg *image.RGBA
    switch sMethod {
    case 0:
        scaledW=targetW; scaledH=targetH
        scaledImg=resizeImage(img, scaledW, scaledH)
    case 1:
        scaleX:=float64(targetW)/float64(srcW); scaleY:=float64(targetH)/float64(srcH)
        scale:=scaleX; if scaleY>scaleX { scale=scaleY }
        scaledW=int(float64(srcW)*scale+0.5); scaledH=int(float64(srcH)*scale+0.5)
        tmp:=resizeImage(img, scaledW, scaledH)
        if scaledW==targetW && scaledH==targetH {
            scaledImg=tmp
        } else {
            offX:=(scaledW-targetW)/2; offY:=(scaledH-targetH)/2
            scaledImg=image.NewRGBA(image.Rect(0,0,targetW,targetH))
            for y:=0;y<targetH;y++{
                for x:=0;x<targetW;x++{
                    scaledImg.Set(x,y, tmp.At(x+offX, y+offY))
                }
            }
            targetW=scaledImg.Bounds().Dx(); targetH=scaledImg.Bounds().Dy()
        }
    case 2:
        scaleX:=float64(targetW)/float64(srcW); scaleY:=float64(targetH)/float64(srcH)
        scale:=scaleX; if scaleY<scaleX { scale=scaleY }
        scaledW=int(float64(srcW)*scale+0.5); scaledH=int(float64(srcH)*scale+0.5)
        if scaledW<2 || scaledH<2 { printLogo(); log.Fatalf("ANSImage: height or width must be >=2") }
        scaledImg=resizeImage(img, scaledW, scaledH)
        targetW=scaledW; targetH=scaledH
        cols=targetW; rows=targetH/2
    }
    for y:=0;y<scaledImg.Bounds().Dy(); y++{
        for x:=0;x<scaledImg.Bounds().Dx(); x++{
            c:=scaledImg.RGBAAt(x,y)
            if c.A!=255 {
                blended:=blendOver(c, matte)
                scaledImg.Set(x,y, blended)
            }
        }
    }
    var out string
    if dMode==0 {
        h:=scaledImg.Bounds().Dy(); w:=scaledImg.Bounds().Dx()
        for y:=0; y<h; y+=2 {
            line:=""
            for x:=0;x<w;x++{
                top:=scaledImg.RGBAAt(x,y)
                var bottom color.RGBA
                if y+1<h { bottom=scaledImg.RGBAAt(x,y+1) } else { bottom=color.RGBA{0,0,0,255} }
                seq:=fmt.Sprintf("\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm\u2584", top.R, top.G, top.B, bottom.R, bottom.G, bottom.B)
                line+=seq
            }
            line+="\x1b[0m\n"
            if goFlag { out+=fmt.Sprintf("fmt.Print(%q)\n", line) } else { out+=line }
        }
    } else {
        h:=scaledImg.Bounds().Dy(); w:=scaledImg.Bounds().Dx()
        for y:=0; y<h; y+=2 {
            line:=""
            for x:=0;x<w;x++{
                top:=scaledImg.RGBAAt(x,y)
                // Use top pixel for dithering (approx)
                lum:=luminance(top.R, top.G, top.B)
                var ch string
                if dMode==1 {
                    if lum < 51 { ch=" " } else if lum < 102 { ch="\u2591" } else if lum < 153 { ch="\u2592" } else if lum < 221 { ch="\u2593" } else { ch="\u2588" }
                } else {
                    // chars mode thresholds
                    if lum < 10 { ch=" " } else if lum < 30 { ch=" " } else if lum < 45 { ch="." } else if lum < 60 { ch=":" } else if lum < 75 { ch=":" } else if lum < 90 { ch=";" } else if lum < 110 { ch="+" } else if lum < 130 { ch="=" } else if lum < 145 { ch="=" } else if lum < 160 { ch="x" } else if lum < 180 { ch="X" } else if lum < 200 { ch="$" } else if lum < 215 { ch="$" } else if lum < 230 { ch="&" } else { ch="#" }
                }
                if nobg {
                    seq:=fmt.Sprintf("\x1b[38;2;%d;%d;%dm%s", top.R, top.G, top.B, ch)
                    line+=seq
                } else {
                    seq:=fmt.Sprintf("\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm%s", matte.R, matte.G, matte.B, top.R, top.G, top.B, ch)
                    line+=seq
                }
            }
            line+="\x1b[0m\n"
            if goFlag { out+=fmt.Sprintf("fmt.Print(%q)\n", line) } else { out+=line }
        }
    }
    fmt.Fprint(os.Stdout, out)
}
