        defer resp.Body.Close()
        if resp.StatusCode!=http.StatusOK { printLogo(); log.Fatalf("ANSImage: image download failed") }
        img, _, err = image.Decode(resp.Body)
        if err != nil { printLogo(); log.Fatalf("image: unknown format") }
    } else {
